  &reftitle.parameters;




     array


पहिलो array।



     arrays


तुलना गर्नका लागि Arrays।



     value_compare_func

      &sort.callback.description;
      &sort.callback.description.presort;



     key_compare_func


keys (indices) को तुलना पनि callback function key_compare_func द्वारा गरिन्छ। यो व्यवहार array_udiff_assoc ले गर्ने भन्दा फरक छ, किनभने पछिल्लोले internal function प्रयोग गरेर indices तुलना गर्दछ।

  &reftitle.examples;



    array_udiff_uassoc को उदाहरण


<?php
class cr {
    private $priv_member;
    function __construct($val)
    {
        $this->priv_member = $val;
    }

    static function comp_func_cr($a, $b)
    {
        if ($a->priv_member === $b->priv_member) return 0;
        return ($a->priv_member > $b->priv_member)? 1:-1;
    }

    static function comp_func_key($a, $b)
    {
        if ($a === $b) return 0;
        return ($a > $b)? 1:-1;
    }
}
$a = array("0.1" => new cr(9), "0.5" => new cr(12), 0 => new cr(23), 1=> new cr(4), 2 => new cr(-15),);
$b = array("0.2" => new cr(9), "0.5" => new cr(22), 0 => new cr(3), 1=> new cr(4), 2 => new cr(-15),);

$result = array_udiff_uassoc($a, $b, array("cr", "comp_func_cr"), array("cr", "comp_func_key"));
print_r($result);
?>


    &example.outputs;


Array
(
    [0.1] => cr Object
        (
            [priv_member:cr:private] => 9
        )

    [0.5] => cr Object
        (
            [priv_member:cr:private] => 12
        )

    [0] => cr Object
        (
            [priv_member:cr:private] => 23
        )
)




  माथिको हाम्रो उदाहरणमा तपाईँ देख्नुहुन्छ कि "1" => new cr(4) pair दुवै arrays मा उपस्थित छ र त्यसैले यो function from आउने output मा पर्दैन। ध्यान दिनुहोस् कि तपाईँले २ वटा callback functions उपलब्ध गराउनुपर्छ।

&reftitle.notes;

 कृपया ध्यान दिनुहोस्, यो function ले n-dimensional array को एउटा dimension मात्र जाँच गर्दछ। अवश्य पनि, तपाईँले उदाहरणका लागि array_udiff_uassoc($array1[0], $array2[0], "data_compare_func",
  "key_compare_func"); प्रयोग गरेर अझ गहिरा dimension हरू जाँच गर्न सक्नुहुन्छ।
